async function llm(env,s,f,t){const r=await env.AI.run('@cf/meta/llama-3.3-70b-instruct-fp8-fast',{messages:[{role:'system',content:`You are a professional technical translator for industrial sealing equipment. Translate the user text from ${LX[f]} to ${LX[t]}. Keep every line break and blank line. Keep all Markdown markers exactly: line prefixes "# ", "## ", "### ", "- ", "> ", and inline **bold**, *italic*, [text](url) (translate the text, keep the url). Leave lines that are only an image path such as /img/abc or /img/abc|l unchanged. Keep brand names, model names, numbers and units. Output only the translation, no notes.`},{role:'user',content:s}],max_tokens:4096,temperature:.2});return String(r.response||'').replace(/^(here is|here's|sure|translation)[^\n]*\n+/i,'').trim()}
