function w2m(h){var d=new DOMParser().parseFromString(h,'text/html'),o=[];
function inl(n){var s='';n.childNodes.forEach(function(c){if(c.nodeType==3){s+=c.textContent.replace(/[\s\u00a0]+/g,' ')}else if(c.nodeType==1){var t=c.tagName,st=(c.getAttribute('style')||'').toLowerCase(),x=inl(c),y=x.trim();if(!y){s+=x;return}if(t=='A'&&/^https?:/.test(c.href||''))y='['+y+']('+c.href+')';else if((t=='B'||t=='STRONG'||/font-weight:\s*(bold|[6-9]00)/.test(st))&&!/^\*\*.*\*\*$/.test(y))y='**'+y+'**';else if((t=='I'||t=='EM'||/font-style:\s*italic/.test(st))&&!/^\*.*\*$/.test(y))y='*'+y+'*';s+=(/^\s/.test(x)?' ':'')+y+(/\s$/.test(x)?' ':'')}});return s}
function blk(n){n.childNodes.forEach(function(c){if(c.nodeType!=1)return;var t=c.tagName,x;
if(/^H[1-6]$/.test(t)){x=inl(c).replace(/\*/g,'').trim();if(x)o.push((t=='H1'||t=='H2'?'## ':'### ')+x)}
else if(t=='P'||(t=='DIV'&&!c.querySelector('p,div,ul,ol,table,h1,h2,h3,h4'))){x=inl(c).trim();if(/MsoListParagraph/.test(c.className||'')||/mso-list/.test(c.getAttribute('style')||'')){if(/^[\u00b7\u2022\u00a7o\-\u2013]\s/.test(x))x='- '+x.replace(/^[\u00b7\u2022\u00a7o\-\u2013]\s*/,'')}else if(/^\*\*[^*]+\*\*$/.test(x)&&x.length<110&&!/[.:]\*\*$/.test(x))x='### '+x.replace(/\*/g,'');if(x)o.push(x)}
else if(t=='UL'||t=='OL'){c.querySelectorAll('li').forEach(function(l){var y=inl(l).trim();if(y)o.push((t=='OL'?'':'- ')+y)})}
else if(t=='TABLE'){c.querySelectorAll('tr').forEach(function(r){var y=[].map.call(r.cells,function(k){return inl(k).trim()}).join(' | ');if(y.replace(/[| ]/g,''))o.push(y)})}
else if(t!='IMG'&&t!='STYLE'&&t!='SCRIPT')blk(c)})}
blk(d.body);return o.join('\n')}
function trn(ty,sl,lg){var t=document.getElementById('trs');if(!t){t=document.createElement('div');t.id='trs';t.className='toast';document.querySelector('.ct').prepend(t)}t.style.background='';t.textContent='Đang dịch sang '+(lg=='vi'?'English':'Tiếng Việt')+'... (khoảng 10-30 giây, bạn có thể tiếp tục làm việc)';var f=new FormData();f.append('type',ty);f.append('slug',sl);f.append('lang',lg);return fetch('/admin/translate',{method:'POST',body:f}).then(function(r){return r.json()}).then(function(j){t.textContent=j.ok?'✓ Đã lưu và dịch xong. Tải lại trang (F5) để xem bản dịch.':'⚠ Chưa dịch được (có thể hết hạn mức AI hôm nay). Bấm "Dịch lại" để thử lại sau.';if(!j.ok)t.style.background='#fff7ed';return j.ok}).catch(function(){t.textContent='⚠ Lỗi kết nối khi dịch. Bấm "Dịch lại" để thử lại.';t.style.background='#fff7ed';return false})}
